"use client";

import "../../styles/teum-base.css";
import "../../styles/components/alert-dialog.css";
import { AlertDialog as AlertDialogPrimitive } from "@base-ui/react/alert-dialog";
import type { ComponentPropsWithRef } from "react";
import { cn } from "../../lib/cn";

export const AlertDialog = AlertDialogPrimitive.Root;
export const AlertDialogTrigger = AlertDialogPrimitive.Trigger;
export const AlertDialogClose = AlertDialogPrimitive.Close;
export const AlertDialogTitle = AlertDialogPrimitive.Title;
export const AlertDialogDescription = AlertDialogPrimitive.Description;

export function AlertDialogContent({ className, children, ...props }: AlertDialogPrimitive.Popup.Props) {
  return (
    <AlertDialogPrimitive.Portal>
      <AlertDialogPrimitive.Backdrop className="teum-dialog__backdrop" />
      <AlertDialogPrimitive.Viewport className="teum-alert-dialog__viewport">
        <AlertDialogPrimitive.Popup className={cn("teum-dialog", "teum-alert-dialog", className)} {...props} data-layer="modal">
          {children}
        </AlertDialogPrimitive.Popup>
      </AlertDialogPrimitive.Viewport>
    </AlertDialogPrimitive.Portal>
  );
}

export function AlertDialogHeader({ className, ...props }: ComponentPropsWithRef<"div">) {
  return <div className={cn("teum-dialog__header", className)} {...props} />;
}

export function AlertDialogFooter({ className, ...props }: ComponentPropsWithRef<"div">) {
  return <div className={cn("teum-dialog__footer", className)} {...props} />;
}

/* Generated from src/styles.css. Do not edit directly. */

@layer teum.tokens, teum.base, teum.components;

@layer teum.components {
.teum-dialog__backdrop { position: fixed; inset: 0; z-index: var(--teum-layer-modal-backdrop); background: var(--teum-bg-scrim); backdrop-filter: blur(1.5px); transition: opacity var(--teum-enter-duration) var(--teum-ease-out); }

.teum-dialog__backdrop[data-starting-style],
.teum-dialog__backdrop[data-ending-style] { opacity: 0; }

.teum-dialog__backdrop[data-ending-style] { transition-duration: var(--teum-exit-duration); }

.teum-dialog { position: fixed; z-index: var(--teum-layer-modal); top: 50%; left: 50%; width: min(390px, calc(100vw - 32px)); padding: 16px; border-radius: var(--teum-radius-overlay); background: var(--teum-bg-modal); box-shadow: var(--teum-shadow-modal); outline: 0; transform: translate(-50%, -50%); transition: opacity var(--teum-enter-duration) var(--teum-ease-out), transform var(--teum-enter-duration) var(--teum-ease-out); }

.teum-dialog[data-starting-style] { opacity: 0; transform: translate(-50%, calc(-50% + 6px)) scale(0.985); }

.teum-dialog[data-ending-style] { opacity: 0; transform: translate(-50%, calc(-50% + 3px)) scale(0.99); transition-duration: var(--teum-exit-duration); }

.teum-dialog__header { display: grid; gap: 7px; padding-right: 28px; }

.teum-dialog__header [data-slot="dialog-title"],
.teum-dialog__header h2 { margin: 0; font-size: 16px; font-weight: 600; letter-spacing: -0.015em; }

.teum-dialog__header [data-slot="dialog-description"],
.teum-dialog__header p { margin: 0; color: var(--teum-ink-secondary); font-size: 13px; line-height: 1.55; }

.teum-dialog__footer { display: flex; justify-content: flex-end; gap: 6px; margin-top: 20px; padding-top: 0; border-top: 0; }

.teum-dialog,
.teum-alert-dialog { background: var(--teum-bg-modal); }

.teum-alert-dialog__viewport { position: fixed; z-index: var(--teum-layer-modal); inset: 0; display: grid; place-items: center; padding: 16px; pointer-events: none; }

.teum-alert-dialog {
  position: relative;
  top: auto;
  left: auto;
  width: min(410px, calc(100vw - 32px));
  background: var(--teum-bg-modal);
  pointer-events: auto;
  transform: translateY(0) scale(1);
}

.teum-alert-dialog .teum-dialog__header { padding-right: 0; }

.teum-alert-dialog[data-starting-style] { opacity: 0; transform: translateY(6px) scale(.985); }

.teum-alert-dialog[data-ending-style] { opacity: 0; transform: translateY(3px) scale(.992); transition-duration: var(--teum-exit-duration); }

@media (prefers-reduced-motion: reduce) {
.teum-dialog,
.teum-dialog__backdrop,
.teum-alert-dialog {
    transition-property: opacity;
    transition-duration: var(--teum-exit-duration);
  }

.teum-alert-dialog[data-starting-style],
.teum-alert-dialog[data-ending-style] { transform: none; }

.teum-dialog[data-starting-style],
.teum-dialog[data-ending-style] { transform: translate(-50%, -50%); }
}
}
